register_round_four_help <- function(){h<-get("parameter_help",envir=parent.frame());for(pre in c("fp_","ob_"))for(k in c("run_source","run_name","config_file","reps","seed","view_scenario","view_trial","sample_run"))h[paste0(pre,k)]<-h[paste0("hg_",k)]
